#!/bin/sh
# build.sh - build the generated PRD HTML for docs/docsHtmlView.
#
# The cover page, section navigation, glossary, _manifest.json, and _meta.json
# are generated by the docs-html-view skill. If docs/toc.yml, CONTEXT.md, or the
# module set changed, re-run that skill first so the generated files are fresh.
#
# This helper is build-only: it never generates content, never installs
# packages, and never looks for the skill directory. It is yours to edit;
# docs-html-view will not overwrite it.
set -eu

cd "$(dirname "$0")"

if [ "$#" -gt 1 ]; then
    echo "usage: $0 [--clean]" >&2
    exit 2
fi

clean=0
case "${1:-}" in
    "") ;;
    --clean) clean=1 ;;
    *)
        echo "usage: $0 [--clean]" >&2
        exit 2
        ;;
esac

PY="${DOCS_PY:-../../.venv-docs/bin/python}"

if [ ! -x "$PY" ]; then
    echo "error: render env not found at $PY; run the docs-html-view skill first." >&2
    exit 1
fi

for name in conf.py guard.py _manifest.json _meta.json index.md; do
    if [ ! -f "$name" ]; then
        echo "error: $name is missing; run the docs-html-view skill first." >&2
        exit 1
    fi
done

if [ "$clean" -eq 1 ]; then
    rm -rf build
fi
mkdir -p build

echo "\"$PY\" -m sphinx -b html -c . -d build/doctrees -w build/warnings.log .. build/html"

"$PY" -m sphinx -b html -c . -d build/doctrees -w build/warnings.log .. build/html || {
    rc=$?
    echo "error: build failed (exit $rc); build/ may contain stale or partial output." >&2
    echo "warnings: $(pwd)/build/warnings.log" >&2
    exit "$rc"
}

warnings=0
if [ -f build/warnings.log ]; then
    warnings=$(awk 'NF > 0 { count++ } END { print count + 0 }' build/warnings.log)
fi

echo "Entry:    $(pwd)/build/html/index.html"
echo "Cover:    $(pwd)/build/html/docsHtmlView/index.html"
echo "Warnings: $warnings ($(pwd)/build/warnings.log)"
